class Solution:
    def minSkips(self, dist: List[int], speed: int, hoursBefore: int) -> int:
        n = len(dist)
        limit = hoursBefore * speed

        def feas(i, t, k):
            t += dist[i]
            if t > limit:
                return False
            if i == n - 1:
                return True
            if k > 0 and feas(i + 1, t, k - 1):
                return True
            return feas(i + 1, (t + speed - 1) // speed * speed, k)

        for k in range(n):
            if feas(0, 0, k):
                return k
        return -1

