class Solution {
    private int[] d;
    private int speed;
    private long limit;

    public int minSkips(int[] dist, int speed, int hoursBefore) {
        d = dist;
        this.speed = speed;
        limit = (long) hoursBefore * speed;
        for (int k = 0; k < dist.length; k++)
            if (feas(0, 0L, k)) return k;
        return -1;
    }

    private boolean feas(int i, long t, int k) {
        t += d[i];
        if (t > limit) return false;
        if (i == d.length - 1) return true;
        if (k > 0 && feas(i + 1, t, k - 1)) return true;
        return feas(i + 1, (t + speed - 1) / speed * speed, k);
    }
}

