class Solution:
    def minSkips(self, dist: List[int], speed: int, hoursBefore: int) -> int:
        n = len(dist)
        limit = hoursBefore * speed
        INF = float('inf')
        dp = [0] + [INF] * n
        for d in dist:
            ndp = [INF] * (n + 1)
            for j in range(n + 1):
                if dp[j] == INF:
                    continue
                t = dp[j] + d
                ndp[j] = min(ndp[j], (t + speed - 1) // speed * speed)
                if j < n:
                    ndp[j + 1] = min(ndp[j + 1], t)
            dp = ndp
        for j in range(n + 1):
            if dp[j] <= limit:
                return j
        return -1

