class Solution {
public:
    int minSkips(vector<int>& dist, int speed, int hoursBefore) {
        int n = dist.size();
        long long limit = (long long)hoursBefore * speed;
        const long long INF = LLONG_MAX / 4;
        vector<long long> dp(n + 1, INF), ndp(n + 1);
        dp[0] = 0;
        for (int d : dist) {
            fill(ndp.begin(), ndp.end(), INF);
            for (int j = 0; j <= n; ++j) {
                if (dp[j] == INF) continue;
                long long t = dp[j] + d;
                ndp[j] = min(ndp[j], (t + speed - 1) / speed * speed);
                if (j < n) ndp[j + 1] = min(ndp[j + 1], t);
            }
            swap(dp, ndp);
        }
        for (int j = 0; j <= n; ++j)
            if (dp[j] <= limit) return j;
        return -1;
    }
};

