    public int minSkips(int[] dist, int speed, int hoursBefore) {
        int n = dist.length;
        long limit = (long) hoursBefore * speed;
        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1], ndp = new long[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int d : dist) {
            Arrays.fill(ndp, INF);
            for (int j = 0; j <= n; j++) {
                if (dp[j] == INF) continue;
                long t = dp[j] + d;
                ndp[j] = Math.min(ndp[j], (t + speed - 1) / speed * speed);
                if (j < n) ndp[j + 1] = Math.min(ndp[j + 1], t);
            }
            long[] tmp = dp; dp = ndp; ndp = tmp;
        }
        for (int j = 0; j <= n; j++)
            if (dp[j] <= limit) return j;
        return -1;
    }
}

